<template>
  <!-- Port of XMCL Me.vue / MeProfilePanel / UserAccountSwitcher layout. -->
  <div class="xmcl-account-page"><aside class="xmcl-account-nav"><div class="xmcl-account-avatar"><q-icon name="person" size="38px"/></div><strong>账户中心</strong><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" @click="section=item.id"><q-icon :name="item.icon"/>{{ item.label }}</button></aside><main class="xmcl-account-content"><template v-if="section==='profile'"><div class="xmcl-account-header"><div><div class="eyebrow">MY ACCOUNT</div><h4>账户与玩家资料</h4><p>管理登录状态、皮肤、披风和认证服务。</p></div><div class="row q-gutter-sm"><q-btn color="primary" label="添加 Microsoft 账户" :disable="busy" @click="loginMicrosoft"/><q-btn flat label="添加离线账户" :disable="busy" @click="offline"/></div></div><AccountPanel :accounts="accounts" :busy="busy" :execute="execute" @changed="onChanged"/></template><template v-else-if="section==='presets'"><div class="xmcl-account-header"><div><div class="eyebrow">AUTHORITY</div><h4>Yggdrasil 服务</h4><p>管理自定义认证服务器预设。</p></div><q-btn color="primary" label="添加服务" @click="addPreset"/></div><q-list bordered separator class="xmcl-preset-list"><q-item v-for="preset in presets" :key="preset.name"><q-item-section><q-item-label>{{ preset.name }} <q-badge v-if="preset.builtin">内置</q-badge></q-item-label><q-item-label caption>{{ preset.authUrl }} · {{ preset.sessionUrl }}</q-item-label></q-item-section><q-item-section side><q-btn v-if="!preset.builtin" flat color="negative" label="删除" :disable="busy" @click="removePreset(preset)"/></q-item-section></q-item><q-item v-if="!presets.length"><q-item-section class="text-grey-5">没有自定义认证服务。</q-item-section></q-item></q-list></template><template v-else><div class="xmcl-account-header"><div><div class="eyebrow">ACCOUNT TOOLS</div><h4>账户操作</h4><p>批量刷新账户并查看认证状态。</p></div></div><q-btn color="primary" label="刷新所有账户" :disable="busy" @click="refreshAll"/><q-list bordered separator class="q-mt-lg"><q-item v-for="a in accounts" :key="a.id"><q-item-section>{{ a.profileName }}</q-item-section><q-item-section side>{{ a.state }}</q-item-section></q-item></q-list></template><q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner></main></div>
</template>
<script setup lang="ts">
import { onMounted, ref } from 'vue';
import AccountPanel from '../components/AccountPanel.vue';
const props=defineProps<{accounts:any[];busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();const emit=defineEmits<{changed:[]}>();const section=ref('profile'),presets=ref<any[]>([]),error=ref('');const sections=[{id:'profile',label:'账户和皮肤',icon:'person'},{id:'presets',label:'认证服务',icon:'dns'},{id:'tools',label:'账户工具',icon:'build'}];
async function loginMicrosoft(){try{await props.execute('account.login',{type:'microsoft'});emit('changed');}catch(e){error.value=String(e);}}
function onChanged(){emit('changed');}
async function loadPresets(){try{const r=await props.execute('account.preset.list');presets.value=Array.isArray(r)?r:[];}catch(e){error.value=String(e);}}
async function offline(){const name=window.prompt('离线玩家名');if(name)try{await props.execute('account.login',{type:'offline',username:name});emit('changed');}catch(e){error.value=String(e);}}
async function refreshAll(){for(const account of props.accounts)try{await props.execute('account.refresh',{account:account.id});}catch(e){error.value=String(e);}emit('changed');}
async function addPreset(){const name=window.prompt('服务名称');const authUrl=window.prompt('认证 URL');const sessionUrl=window.prompt('会话 URL');if(!name||!authUrl||!sessionUrl)return;try{await props.execute('account.preset.add',{name,authUrl,sessionUrl});await loadPresets();}catch(e){error.value=String(e);}}
async function removePreset(p:any){try{await props.execute('account.preset.remove',{name:p.name,confirm:true});await loadPresets();}catch(e){error.value=String(e);}}
onMounted(loadPresets);
</script>
<style scoped>.xmcl-account-page{display:flex;min-height:680px;max-width:1250px;margin:0 auto}.xmcl-account-nav{width:250px;min-width:250px;padding:30px 18px;display:flex;flex-direction:column;align-items:stretch;gap:5px;border-right:1px solid rgba(255,255,255,.1)}.xmcl-account-avatar{width:76px;height:76px;border-radius:24px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#6366f1,#312e81);margin-bottom:14px}.xmcl-account-nav strong{font-size:18px;margin-bottom:18px}.xmcl-account-nav button{display:flex;align-items:center;gap:10px;padding:12px;border:0;border-radius:10px;background:transparent;color:rgba(255,255,255,.65);text-align:left;cursor:pointer}.xmcl-account-nav button:hover,.xmcl-account-nav button.active{background:rgba(129,140,248,.2);color:#fff}.xmcl-account-content{flex:1;min-width:0;padding:30px}.xmcl-account-header{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:24px}.xmcl-account-header h4{margin:4px 0;font-size:26px}.xmcl-account-header p{margin:0;color:rgba(255,255,255,.55)}.eyebrow{font-size:11px;letter-spacing:.14em;color:#a5b4fc;font-weight:700}.xmcl-preset-list{max-width:900px}@media(max-width:800px){.xmcl-account-page{display:block}.xmcl-account-nav{width:auto;min-width:0;border-right:0;border-bottom:1px solid rgba(255,255,255,.1);flex-direction:row;align-items:center;overflow:auto}.xmcl-account-avatar,.xmcl-account-nav strong{display:none}.xmcl-account-content{padding:20px 12px}.xmcl-account-header{display:block}.xmcl-account-header .row{margin-top:14px}}
</style>
